const filterProducts = (catalog: Product[], term: string, category: string, sortBy: string, maxPrice: number) => {
  const normalized = term.toLowerCase();
  return [...catalog]
    .filter((product) => {
    const matchesCategory =
      category === 'All'
        ? true
        : category === 'Best Sellers'
          ? Boolean(product.bestseller)
          : category === 'New Arrivals'
            ? Boolean(product.newArrival)
            : product.category === category;
    const matchesSearch =
      product.name.toLowerCase().includes(normalized) ||
      product.category.toLowerCase().includes(normalized) ||
      product.description.toLowerCase().includes(normalized);
    const matchesPrice = product.salePrice ? product.salePrice <= maxPrice : product.price <= maxPrice;
    return matchesCategory && matchesSearch && matchesPrice;
  })
  .sort((a, b) => {
      switch (sortBy) {
        case 'price-low':
          return (a.salePrice ?? a.price) - (b.salePrice ?? b.price);
        case 'price-high':
          return (b.salePrice ?? b.price) - (a.salePrice ?? a.price);
        case 'newest':
          return Number(b.newArrival) - Number(a.newArrival);
        case 'popularity':
          return b.rating - a.rating;
        default:
          return Number(b.featured) - Number(a.featured);
      }
    });
};

const getFeaturedProducts = (catalog: Product[], category?: string) => {
  const source = category ? catalog.filter((product) => product.category === category) : catalog;
  return source.filter((product) => product.featured || product.bestseller || product.newArrival).slice(0, 4);
};

